"use strict";
exports.useLogger = (logger) => {
  logger.log("island via logger", 1, { a: [1, 2] });
  logger.error("island error %d", 2);
  return typeof logger.log;
};
exports.callFn = (fn) => {
  fn("island via function %s", "formatted", { b: 1 });
};
exports.isConsole = (value) => value === console;
exports.describe = (value) => typeof value + ":" + typeof value.log + ":" + typeof value.table;
exports.useUntyped = (value) => {
  value.log("island untyped", 3);
  value.warn("island warn");
  return value === console;
};
